/* ============================================================
   thaisound3.js — เสียงเครื่องดนตรีชุดที่ 3 (อัดจริงในห้อง 512 เมื่อ 29 ต.ค. 2569) + เสียงสังเคราะห์
   อัดจริง: กลองทัด (คู่) · ตะโพน · ซออู้ (ไล่เสียง 9 โน้ต ลดเสียงซ่าแล้ว) · เสียงร้องเอื้อนของครูตังค์
   สังเคราะห์: ปี่แน (สร้างจากสเปกตรัมฮาร์มอนิกที่วัดจากคลิปสอนปี่แนเล็ก ไม่ได้ใช้เสียงจากคลิปนั้นโดยตรง)
   ใช้: TS3.init(audioContext, outputNode) แล้วเรียก
     TS3.that(k,t,v)        กลองทัด k 0 = ลูกเสียงต่ำ · 1 = ลูกเสียงสูง
     TS3.taphon(k,t,v)      ตะโพน k 0 เสียงทุ้มก้อง · 1 เสียงกลาง · 2 เสียงปิดสั้น · 3 เสียงตบ
     TS3.sorou(f,t,dur,v)   ซออู้ที่ความถี่ f (เลือกโน้ตอัดที่ใกล้ที่สุดแล้วปรับระดับ ค้างเสียงได้)
     TS3.voice(t,v,out,dur) เสียงเอื้อน (ทั้งท่อนราว 25 วินาที หรือกำหนด dur) · คืนค่าตัวควบคุม {stop()}
     TS3.voiceNote(f,t,dur,v) เสียงร้อง “อา” ค้างที่ความถี่ f
     TS3.pinae(f,t,dur,v)   ปี่แน (สังเคราะห์) · TS3.PINAEF ระดับเสียงปี่แนเล็กที่วัดได้ (โด–ที สองช่วงเสียง)
   พัฒนาโดย นายนนทพัทธ์ วงค์มูล 2026
   ============================================================ */
(function(){
  'use strict';
  const SRC={"th_0": "data:audio/mpeg;base64,", "th_1": "data:audio/mpeg;base64,", "tp_0": "data:audio/mpeg;base64,", "tp_1": "data:audio/mpeg;base64,", "tp_2": "data:audio/mpeg;base64,", "tp_3": "data:audio/mpeg;base64,", "su_229": "data:audio/mpeg;base64,", "su_257": "data:audio/mpeg;base64,", "su_289": "data:audio/mpeg;base64,", "su_304": "data:audio/mpeg;base64,", "su_344": "data:audio/mpeg;base64,", "su_386": "data:audio/mpeg;base64,", "su_429": "data:audio/mpeg;base64,", "su_459": "data:audio/mpeg;base64,", "su_517": "data:audio/mpeg;base64,", "vo_phrase": "data:audio/mpeg;base64,", "vo_238": "data:audio/mpeg;base64,"};
  const SORU=[229,257,289,304,344,386,429,459,517];
  let AC=null,OUT=null;const B={};
  function init(ac,out){if(AC===ac)return;AC=ac;OUT=out||ac.destination;
    Object.keys(SRC).forEach(k=>{fetch(SRC[k]).then(r=>r.arrayBuffer()).then(ab=>new Promise((res,rej)=>AC.decodeAudioData(ab,res,rej))).then(b=>{
      const d=b.getChannelData(0);let m=0;for(let i=0;i<d.length;i++)m=Math.max(m,Math.abs(d[i]));let s=0;while(s<d.length&&Math.abs(d[s])<m*.04)s++;B[k]={b,off:Math.max(0,s/b.sampleRate-.002)}}).catch(()=>{})})}
  const ready=k=>!!(k?B[k]:Object.keys(SRC).every(x=>B[x]));
  function play(key,t,v,rate,dur,out,loop){const s=B[key];if(!AC||!s)return null;t=Math.max(t||0,AC.currentTime);rate=rate||1;
    const n=AC.createBufferSource(),g=AC.createGain();n.buffer=s.b;n.playbackRate.value=rate;g.gain.setValueAtTime(v==null?1:v,t);
    if(dur){const len=(s.b.duration-s.off)/rate;if(loop&&dur>len-.2){n.loop=true;n.loopStart=Math.min(s.b.duration-.45,s.off+.4);n.loopEnd=s.b.duration-.25}
      g.gain.setValueAtTime(v==null?1:v,t+Math.max(.05,dur-.1));g.gain.linearRampToValueAtTime(0,t+dur+.08)}
    n.connect(g);g.connect(out||OUT);n.start(t,s.off);if(dur)n.stop(t+dur+.12);
    return {stop(){try{const e=AC.currentTime;g.gain.cancelScheduledValues(e);g.gain.setValueAtTime(g.gain.value,e);g.gain.linearRampToValueAtTime(0,e+.12);n.stop(e+.15)}catch(x){}}}}
  function near(list,f){let b=list[0];list.forEach(x=>{if(Math.abs(Math.log(x/f))<Math.abs(Math.log(b/f)))b=x});return b}
  /* ปี่แนสังเคราะห์: ความดังของฮาร์มอนิกตามย่านความถี่วัดจากคลิป (เด่นที่ราว 1.4 และ 3 kHz) มีเสียงลม เสียงสั่นเล็กน้อย และเปิดเสียงจากต่ำกว่าเล็กน้อยแบบคนเป่า */
  const ENV=[[200,.5],[320,.51],[490,.39],[720,.35],[1020,.3],[1400,.95],[1850,.47],[2400,.37],[3050,.67],[3850,.16],[4650,.06],[7000,.01]];
  function env(F){if(F<=ENV[0][0])return ENV[0][1];for(let i=1;i<ENV.length;i++)if(F<=ENV[i][0]){const [f0,a0]=ENV[i-1],[f1,a1]=ENV[i],u=Math.log(F/f0)/Math.log(f1/f0);return a0+(a1-a0)*u}return .01}
  function pinae(f,t,dur,v,out){if(!AC)return null;t=Math.max(t||0,AC.currentTime);dur=dur||.5;v=(v==null?1:v)*.11;
    const g=AC.createGain(),lp=AC.createBiquadFilter();lp.type='lowpass';lp.frequency.value=6500;g.connect(lp);lp.connect(out||OUT);
    g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+.04);g.gain.setValueAtTime(v,t+Math.max(.05,dur-.06));g.gain.linearRampToValueAtTime(0,t+dur+.05);
    const vib=AC.createOscillator(),vg=AC.createGain();vib.frequency.value=5.4;vg.gain.value=f*.006;vib.connect(vg);
    const nh=Math.min(16,Math.floor(7000/f));const oscs=[];
    for(let k=1;k<=nh;k++){const o=AC.createOscillator(),a=AC.createGain();o.frequency.setValueAtTime(f*k*.985,t);o.frequency.exponentialRampToValueAtTime(f*k,t+.06);
      const kg=AC.createGain();kg.gain.value=k;vg.connect(kg);kg.connect(o.frequency);a.gain.value=env(f*k)*.75;o.connect(a);a.connect(g);o.start(t);o.stop(t+dur+.1);oscs.push(o)}
    vib.start(t);vib.stop(t+dur+.1);
    const nb=AC.createBuffer(1,Math.floor(AC.sampleRate*(dur+.1)),AC.sampleRate),d=nb.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
    const ns=AC.createBufferSource(),bp=AC.createBiquadFilter(),ng=AC.createGain();ns.buffer=nb;bp.type='bandpass';bp.frequency.value=2600;bp.Q.value=1.2;ng.gain.value=.05;ns.connect(bp);bp.connect(ng);ng.connect(g);ns.start(t);
    return {stop(){try{const e=AC.currentTime;g.gain.cancelScheduledValues(e);g.gain.setValueAtTime(g.gain.value,e);g.gain.linearRampToValueAtTime(0,e+.06);oscs.forEach(o=>o.stop(e+.08));ns.stop(e+.08)}catch(x){}}}}
  window.TS3={init,ready,SORU,
    PINAEF:[310,351,380,420,470,518,551,619,701,755,837,929,994,1072],
    that:(k,t,v,out)=>play(k?'th_1':'th_0',t,v,1,0,out),
    taphon:(k,t,v,out)=>play('tp_'+Math.max(0,Math.min(3,k|0)),t,v,1,0,out),
    sorou:(f,t,dur,v,out)=>{const s=near(SORU,f);return play('su_'+s,t,v,f/s,dur||.6,out,true)},
    voice:(t,v,out,dur)=>play('vo_phrase',t,v,1,dur||0,out),
    voiceNote:(f,t,dur,v,out)=>play('vo_238',t,v,f/238,dur||.8,out,true),
    pinae};
})();
